```typescript
it('interpolates opacity from 0 to target at t=0.5', () => {
  const fn = spec.enterFn({ ...defaultState, style: { ...defaultStyle, baseOpacity: 0.8 } });
  const result = fn({ t: 0.5 });
  expect(result.style.baseOpacity).toBeCloseTo(0.4);
});
```

Widget tests: construct, call `apply()` with real state, assert observable effects on Three.js objects. Tests live in `__tests__/` co-located with the source.

`createSlideTheme` deep-merges partial overrides into `defaultSlideTheme`. Only specify the fields you want to change.

```typescript
function createSlideTheme(overrides: DeepPartial<SlideTheme>): SlideTheme;
```

```tsx
import { SlidePlayer, createSlideTheme } from '@brewsite/slides';

const brandTheme = createSlideTheme({
  timing: {
    transitionDuration: '400ms',
    entranceDuration: 0.4,
    staggerDelay: 0.1,
  },
  density: {
    contentPadding: '56px',
    titleHeight: 0.2,
  },
  typography: {
    headingScale: 1.3,
  },
});

<SlidePlayer slideTheme={brandTheme}>
  {/* slides */}
</SlidePlayer>
